  1→import { create } from 'zustand';
  2→import { devtools, persist } from 'zustand/middleware';
  3→import { immer } from 'zustand/middleware/immer';
  4→
  5→// Import necessary types from other modules
  6→import { MoodCategory, Whisper, WHISPERS } from '../data/whispers';
  7→import useAtlasStore, { AtlasState } from './useAtlasStore'; // Import actual AtlasState
  8→
  9→// --- Action type for mood detection ---
 10→interface Action {
 11→  type: string; // e.g., 'query', 'error', 'milestone', 'session_start', 'view_change'
 12→  timestamp: number;
 13→}
 14→
 15→// --- Mood Detection Logic ---
 16→// This function determines the user's mood based on recent activity and system state.
 17→
 18→const MAX_ACTIONS_HISTORY = 50; // Limit history to keep it manageable
 19→let recentActionsHistory: Action[] = []; // Store actions to track user activity
 20→
 21→function addActionToHistory(action: Action) {
 22→  recentActionsHistory.unshift(action); // Add to the beginning
 23→  if (recentActionsHistory.length > MAX_ACTIONS_HISTORY) {
 24→    recentActionsHistory.pop(); // Remove the oldest action
 25→  }
 26→}
 27→
 28→function detectMood(currentAtlasState: AtlasState): MoodCategory {
 29→  const errorCount = recentActionsHistory.filter(a => a.type === 'error').length;
 30→  const queryCount = recentActionsHistory.filter(a => a.type === 'query').length;
 31→  const lastQueryTimestamp = recentActionsHistory.find(a => a.type === 'query')?.timestamp ?? 0;
 32→  const lastQueryAge = Date.now() - lastQueryTimestamp;
 33→
 34→  // --- Mood Heuristics (as per IMPLEMENTATION_SPEC.md) ---
 35→
 36→  // Frustrated: Multiple errors without significant query progress
 37→  if (errorCount > 2 && queryCount < 4 && lastQueryAge < 60_000) return 'frustrated';
 38→
 39→  // Triumphant: High consensus score achieved with some activity
 40→  if (currentAtlasState.consensusScore > 90 && queryCount > 0) return 'triumphant';
 41→
 42→  // Idle: No activity for a while
 43→  if (lastQueryAge > 60_000) return 'idle'; // 60 seconds
 44→
 45→  // Focused: Many queries indicating deep work
 46→  if (queryCount > 5) return 'focused';
 47→
 48→  // Entering: Very few queries, early in session
 49→  if (queryCount <= 2 && lastQueryAge < 30_000) return 'entering'; // Within first 30s
 50→
 51→  // Default/Exploring: Anything else, suggesting general browsing or moderate activity
 52→  return 'exploring';
 53→}
 54→
 55→
 56→// --- Whisper Store ---
 57→
 58→interface WhisperStoreState {
 59→  currentWhisper: Whisper | null;
 60→  whisperQueue: Whisper[];
 61→  mood: MoodCategory;
 62→  lastMoodChangeTime: number;
 63→  lastActionTime: number;
 64→  isShowingWhisper: boolean;
 65→
 66→  // Actions
 67→  addWhisperToQueue: (whisper: Whisper) => void;
 68→  showNextWhisper: () => void;
 69→  dismissWhisper: () => void;
 70→  updateMood: (currentAtlasState: AtlasState) => void; // Accept actual AtlasState
 71→  recordAction: (actionType: Action['type']) => void;
 72→  autoDismissTimer: NodeJS.Timeout | null;
 73→  clearAutoDismissTimer: () => void;
 74→}
 75→
 76→const useWhisperStore = create<WhisperStoreState>()(
 77→  devtools(
 78→    persist(
 79→      immer((set, get) => ({
 80→        currentWhisper: null,
 81→        whisperQueue: [],
 82→        mood: 'entering', // Initial mood
 83→        lastMoodChangeTime: Date.now(),
 84→        lastActionTime: Date.now(),
 85→        isShowingWhisper: false,
 86→        autoDismissTimer: null,
 87→
 88→        // --- Actions ---
 89→        addWhisperToQueue: (whisper: Whisper) => {
 90→          set(state => {
 91→            state.whisperQueue.push(whisper);
 92→            // If no whisper is currently showing, try to show the next one
 93→            if (!state.isShowingWhisper) {
 94→              get().showNextWhisper();
 95→            }
 96→          });
 97→        },
 98→
 99→        showNextWhisper: () => {
100→          const { whisperQueue, currentWhisper, isShowingWhisper, autoDismissTimer } = get();
101→
102→          if (isShowingWhisper || whisperQueue.length === 0) {
103→            return;
104→          }
105→
106→          if (autoDismissTimer) {
107→            clearTimeout(autoDismissTimer);
108→            set({ autoDismissTimer: null });
109→          }
110→
111→          set(state => {
112→            const nextWhisper = state.whisperQueue.shift();
113→            if (nextWhisper) {
114→              state.currentWhisper = nextWhisper;
115→              state.isShowingWhisper = true;
116→              // Set auto-dismiss timer (8 seconds as per spec)
117→              const timer = setTimeout(() => {
118→                get().dismissWhisper();
119→              }, 8000);
120→              state.autoDismissTimer = timer;
121→            }
122→          });
123→        },
124→
125→        dismissWhisper: () => {
126→          set(state => {
127→            state.currentWhisper = null;
128→            state.isShowingWhisper = false;
129→            state.autoDismissTimer = null;
130→            get().showNextWhisper(); // Try to show next in queue
131→          });
132→        },
133→
134→        updateMood: (currentAtlasState: AtlasState) => {
135→          const newMood = detectMood(currentAtlasState);
136→          const { mood: currentMood, lastMoodChangeTime, isShowingWhisper, whisperQueue } = get();
137→          const currentTime = Date.now();
138→          const MOOD_CHANGE_DEBOUNCE_MS = 10000; // 10 seconds
139→
140→          if (newMood !== currentMood && (currentTime - lastMoodChangeTime > MOOD_CHANGE_DEBOUNCE_MS)) {
141→            set(state => {
142→              state.mood = newMood;
143→              state.lastMoodChangeTime = currentTime;
144→              // If mood changes and no whisper is showing, try to show one for the new mood
145→              if (!state.isShowingWhisper && whisperQueue.length === 0) {
146→                const relevantWhispers = WHISPERS.filter(w => w.mood === newMood);
147→                if (relevantWhispers.length > 0) {
148→                  const randomWhisper = relevantWhispers[Math.floor(Math.random() * relevantWhispers.length)];
149→                  state.whisperQueue.push(randomWhisper);
150→                  get().showNextWhisper();
151→                }
152→              }
153→            });
154→          }
155→        },
156→
157→        recordAction: (actionType: Action['type']) => {
158→          const currentTime = Date.now();
159→          addActionToHistory({ type: actionType, timestamp: currentTime });
160→          set({ lastActionTime: currentTime });
161→          // Re-evaluate mood after action
162→          // Get the actual AtlasState to pass to updateMood
163→          const atlasState = useAtlasStore.getState(); // Accessing zustand store state directly
164→          get().updateMood(atlasState);
165→        },
166→
167→        clearAutoDismissTimer: () => {
168→          const { autoDismissTimer } = get();
169→          if (autoDismissTimer) {
170→            clearTimeout(autoDismissTimer);
171→            set({ autoDismissTimer: null });
172→          }
173→        },
174→      })),
175→      {
176→        name: 'whisper-storage',
177→      }
178→    ),
179→    { name: 'WhisperStore' }
180→  )
181→);
182→
183→// Export helper to get the current mood and actions
184→export const useWhisperState = (selector: (state: WhisperStoreState) => any) => {
185→  const state = useWhisperStore(selector);
186→  return state;
187→};
188→
189→export default useWhisperStore;
190→

