  3→
  4→// --- Mock/Helper Types and Functions ---
  5→// These would typically be imported from other modules.
  6→// Mocking them here for self-containment as per the spec's intent.
  7→
  8→interface SessionEntry {
  9→  id: string;
 10→  ontology: string;
 11→  result: {
 12→    consensus_score: number;
 13→    // ... other properties from tribunal results
 14→  };
 15→  timestamp: number;
 16→  label?: string; // Optional label for context
 17→}
 18→
 19→interface ContextDensity {
 20→  id: string;
 21→  label: string;                    // e.g. "cancer medicine", "weed shops"
 22→  density: number;                  // 0.0 (vapor) → 1.0 (solid)
 23→  consistency: number;              // 0.0 (contradictory) → 1.0 (aligned)
 24→  vectorField: Vector3[];           // Directional flow arrows
 25→  color: string;                    // Derived from ontology/mood
 26→  position: [number, number, number]; // 3D placement
 27→}
 28→
 29→function mean(arr: number[]): number {
 30→  if (arr.length === 0) return 0;
 31→  return arr.reduce((sum, val) => sum + val, 0) / arr.length;
 32→}
 33→
 34→function standardDeviation(arr: number[]): number {
 35→  if (arr.length < 2) return 0;
 36→  const m = mean(arr);
 37→  // Using sample standard deviation (n-1)
 38→  const variance = arr.reduce((sum, val) => sum + Math.pow(val - m, 2), 0) / (arr.length - 1);
 39→  return Math.sqrt(variance);
 40→}
 41→
 42→function groupBy<T>(list: T[], getKey: (item: T) => string): Record<string, T[]> {
 43→  return list.reduce((acc, item) => {
 44→    const key = getKey(item);
 45→    if (!acc[key]) {
 46→      acc[key] = [];
 47→    }
 48→    acc[key].push(item);
 49→    return acc;
 50→  }, {} as Record<string, T[]>);
 51→}
 52→
 53→function extractConsensusScore(result: any): number {
 54→  // Placeholder: In a real app, this would extract the score from the result object
 55→  return result?.consensus_score ?? 0;
 56→}
 57→
 58→const ONTOLOGY_COLOR_MAP: Record<string, string> = {
 59→  'pharmacology': '#10b981', // emerald
 60→  'biochemistry': '#f59e0b', // amber
 61→  'logic': '#8b5cf6', // violet
 62→  'topology': '#f43f5e', // rose
 63→  'systems biology': '#6366f1', // indigo
 64→  'general': '#06b6d4', // cyan
 65→};
 66→
 67→// Mock function to map a label (like 'cancer medicine') to an ontology key
 68→function getOntologyKeyForLabel(label: string): string {
 69→  const lowerLabel = label.toLowerCase();
 70→  if (lowerLabel.includes('cancer') || lowerLabel.includes('medicine')) return 'pharmacology';
 71→  if (lowerLabel.includes('shop') || lowerLabel.includes('retail')) return 'general';
 72→  // Add more mappings as needed for other ontologies
 73→  return 'general'; // Default ontology
 74→}
 75→
 76→// --- Density Analysis Store ---
 77→
 78→interface DensityAnalysisState {
 79→  sessions: SessionEntry[];
 80→  contextDensities: ContextDensity[];
 81→  updateSessions: (newSessions: SessionEntry[]) => void;
 82→  computeDensity: () => void;
 83→}
 84→
 85→const useDensityAnalysis = create<DensityAnalysisState>((set, get) => ({
 86→  sessions: [],
 87→  contextDensities: [],
 88→
 89→  updateSessions: (newSessions: SessionEntry[]) => {
 90→    set({ sessions: newSessions });
 91→    // Recompute density immediately after sessions update
 92→    get().computeDensity();
 93→  },
 94→
 95→  computeDensity: () => {
 96→    const { sessions } = get();
 97→    if (sessions.length === 0) {
 98→      set({ contextDensities: [] });
 99→      return;
100→    }
101→
102→    // Cluster sessions by ontology derived from session label/ontology
103→    const clusters = groupBy(sessions, s => getOntologyKeyForLabel(s.label ?? s.ontology ?? 'general'));
104→
105→    const computedDensities: ContextDensity[] = [];
106→
107→    Object.entries(clusters).forEach(([ontologyKey, entries], index) => {
108→      if (entries.length === 0) return;
109→
110→      const scores = entries.map(e => extractConsensusScore(e.result));
111→      const avgScore = mean(scores);
112→      const variance = standardDeviation(scores);
113→
114→      // Density calculation: based on number of sessions and average consensus
115→      // Scale factor 10 and 100 are empirical, adjust as needed
116→      const density = Math.min(1.0, (entries.length / 10) * (avgScore / 100));
117→      // Consistency calculation: inversely related to variance
118→      const consistency = Math.max(0.0, 1.0 - variance / 50); // Max variance of 50 maps to consistency 0
119→
120→      // Vector field: temporal gradient of scores (simplified)
121→      const vectors: Vector3[] = scores.map((s, i) => {
122→        const nextScore = scores[i + 1] ?? s;
123→        const scoreChange = nextScore - s;
124→        const magnitude = Math.abs(scoreChange);
125→        // Simplified vector direction and magnitude calculation
126→        // This can be made more sophisticated based on temporal or semantic relationships
127→        const direction = new Vector3(
128→          Math.cos(i * 0.5) * scoreChange * 0.1,
129→          Math.sin(i * 0.5) * scoreChange * 0.1,
130→          scoreChange * 0.05 // Z component for temporal progression?
131→        );
132→        return direction.normalize().multiplyScalar(magnitude);
133→      });
134→
135→      const baseColor = ONTOLOGY_COLOR_MAP[ontologyKey] || ONTOLOGY_COLOR_MAP['general'];
136→      // Modulate color saturation based on consistency (e.g., higher consistency = more vivid)
137→      // This is a simplified approach; a real implementation might use HSL color manipulation
138→      const saturationFactor = consistency; // 0 = desaturated, 1 = vivid
139→      const finalColor = colorWithSaturation(baseColor, saturationFactor); // Function to adjust saturation
140→
141→      computedDensities.push({
142→        id: `density-${index}-${ontologyKey}`,
143→        label: entries[0].label || ontologyKey, // Use provided label or ontology key
144→        density: density,
145→        consistency: consistency,
146→        vectorField: vectors,
147→        color: finalColor,
148→        position: [
149→          Math.sin(index * 0.5) * 5, // Distribute horizontally
150→          -2, // Fixed Y position below islands as per spec
151→          Math.cos(index * 0.5) * 5
152→        ],
153→      });
154→    });
155→
156→    // Sort by density (highest first) for rendering priority
157→    computedDensities.sort((a, b) => b.density - a.density);
158→
159→    set({ contextDensities: computedDensities });
160→  },
161→}));
162→
163→// Helper function for color saturation (example implementation)
164→function colorWithSaturation(hex: string, factor: number): string {
165→  // Basic method: adjust brightness/saturation. More advanced would use HSL.
166→  // For simplicity, let's just make it slightly dimmer if consistency is low.
167→  if (factor >= 0.8) return hex;
168→  if (factor < 0.5) return hex.replace(/([0-9A-F]{2})/g, (match) => {
169→      const val = parseInt(match, 16);
170→      return Math.floor(val * (0.5 + factor * 0.5)).toString(16).padStart(2, '0');
171→  });
172→  return hex;
173→}
174→
175→
176→export default useDensityAnalysis;
