def ask_vision(
    self,
    image_path: str,
    prompt: str,
    model: str = "",
    tier: str = "cheap",
    max_tokens: int = 1024,
) -> ModelResponse:
    """Send an image + text prompt to a vision-capable model via LiteLLM."""
    import base64, mimetypes

    mime, _ = mimetypes.guess_type(image_path)
    if not mime:
        mime = "image/png"
    with open(image_path, "rb") as f:
        b64 = base64.b64encode(f.read()).decode()

    content = [
        {"type": "text", "text": prompt},
        {"type": "image_url", "image_url": {"url": f"data:{mime};base64,{b64}"}},
    ]

    if not model:
        tier_cfg = self.tiers.get(tier, {})
        for candidate in tier_cfg.get("candidates", []):
            provider_name, model_id = self._resolve_model(candidate)
            cfg = self.providers.get(provider_name)
            if not cfg:
                continue
            api_key = os.environ.get(cfg.api_key_env, "")
            if not api_key and cfg.name == "gemini":
                api_key = os.environ.get("GEMINI_T1_API_KEY", "")
            if api_key:
                model = candidate
                break
        if not model:
            return ModelResponse(
                provider="", model="", text="", latency_s=0, tier=tier,
                error="No vision-capable model available",
            )

    provider_name, model_id = self._resolve_model(model)
    t0 = time.time()
    try:
        messages = [{"role": "user", "content": content}]
        response = litellm.completion(
            model=model, messages=messages,
            temperature=0.3, max_tokens=max_tokens,
        )
        text = response.choices[0].message.content
        usage = getattr(response, 'usage', {})
        elapsed = time.time() - t0
        _log_call(
            provider_name, model_id,
            getattr(usage, 'prompt_tokens', 0),
            getattr(usage, 'completion_tokens', 0),
            getattr(usage, 'total_tokens', 0),
            elapsed * 1000, None,
        )
        return ModelResponse(
            provider=provider_name, model=model_id,
            text=text, latency_s=round(elapsed, 2),
            tokens_used=getattr(usage, 'total_tokens', 0),
            tier=tier,
        )
    except Exception as e:
        elapsed = time.time() - t0
        _log_call(provider_name, model_id, 0, 0, 0, elapsed * 1000, str(e))
        return ModelResponse(
            provider=provider_name, model=model_id,
            text="", latency_s=round(elapsed, 2), error=str(e),
        )

